@dataclass(frozen=True, slots=True, kw_only=True)
class IndexRunView:
    """One update or rebuild of the search index: its model, who started it and when, and the version it made or the error it stopped on."""
    action: Literal["update", "rebuild"]
    model_id: str
    actor: str
    at: str
    correlation_id: str
    version: str | None = None
    products: int
    embedded: int
    removed: int
    error: str | None = None

@dataclass(frozen=True, slots=True, kw_only=True)
class IndexStatus:
    """The search index against the catalog, as `radar index status` and the admin read it: the current version's embedder and products, when it was built, and the last runs; only the catalog and the runs before the first build."""
    version: str | None = None
    embedder: EmbedderModel | None = None
    products_indexed: int | None = None
    products_in_catalog: int
    built_at: str | None = None
    runs: tuple[IndexRunView, ...]

@dataclass(frozen=True, slots=True, kw_only=True)
class IndexSettings:
    """The embedding model the live index is built with, and search.json's settings: its model and the ranking and retrieval knobs."""
    current: EmbedderModel | None = None
    search: SearchSettings

@dataclass(frozen=True, slots=True, kw_only=True)
class MatchView:
    """Why a product matched a query: the query terms found in a field, or in a published value (its spec key and label)."""
    field: str
    terms: tuple[str, ...]
    key: str | None = None
    label: str | None = None

@dataclass(frozen=True, slots=True, kw_only=True)
class SearchHitView:
    """A product a query found, as `radar product search` prints it: its score, why it matched and its rank in each ranking."""
    id: str
    slug: str
    name: str
    vendor: str
    vendor_name: str
    category: str
    score: float
    why: tuple[MatchView, ...]
    rank_sources: Mapping[str, int]

@dataclass(frozen=True, slots=True, kw_only=True)
class SearchHits:
    """What a query finds, ranked: the admin's search console and the MCP server's search_products."""
    hits: tuple[SearchHitView, ...]

@dataclass(frozen=True, slots=True, kw_only=True)
class AiCapRow:
    """One AI use's model, prompt and caps (the registry's defaults, or its AiCap record) against its spend of the month and its calls of the day; all uses together have caps only."""
    use: Use
    cap: str
    model: str | None = None
    prompt: str | None = None
    month_cad: float
    day_calls: int
    client_calls: int | None = None
    cad_month: float
    calls_today: int

@dataclass(frozen=True, slots=True, kw_only=True)
class AiCaps:
    """Every AI use's settings and usage on a day, all AI together first, and the models a use may run with their prices, counted in CAD at `cad_per_usd`."""
    day: str
    cad_per_usd: float
    models: tuple[AiModel, ...]
    uses: tuple[AiCapRow, ...]

@dataclass(frozen=True, slots=True, kw_only=True)
class WeekCounts:
    """One week of the site's anonymous counters, Monday to the week's last counted day, with the search KPIs a week has data for."""
    week: str
    to: str
    counts: Mapping[str, int]
    kpis: Mapping[str, float]

@dataclass(frozen=True, slots=True, kw_only=True)
class WeeklyCounts:
    """The site's anonymous counters week by week, newest first, read from `metrics/` and never estimated."""
    weeks: tuple[WeekCounts, ...]

@dataclass(frozen=True, slots=True, kw_only=True)
class StoredFile:
    """A file the admin put into the BlobStore: its digest, type and size."""
    sha256: str
    mime: str
    bytes: int

@dataclass(frozen=True, slots=True, kw_only=True)
class AgentLimits:
    """What one outside agent may do with its token: calls a minute and proposals a day."""
    requests_per_minute: int
    proposals_per_day: int

@dataclass(frozen=True, slots=True, kw_only=True)
class AgentTokenView:
    """An outside agent's token as `radar agent-token list` and the admin show it: never the token, nor its digest. It works until the day it expires."""
    id: str
    name: str
    scope: Scope
    expires: str
    created_at: str
    limits: AgentLimits
    status: Standing
    revoked_at: str | None = None

@dataclass(frozen=True, slots=True, kw_only=True)
class AgentTokenList:
    """A page of the outside agents' tokens, newest first, how many there are, and the limits a new one gets unless it is given its own."""
    tokens: tuple[AgentTokenView, ...]
    limits: AgentLimits
    next: str | None = None
    total: int

    @property
    def cursor(self) -> str | None:
        return self.next

@dataclass(frozen=True, slots=True, kw_only=True)
class IssuedToken:
    """A token just issued: the token itself, shown this once, beside its view."""
    agent: AgentTokenView
    token: str

@dataclass(frozen=True, slots=True, kw_only=True)
class ResearchLine:
    """One step of a research run: a page or file read or skipped and why, a proposal filed (a page's, a staged file's or a datasheet's), why one was rejected, or why the run ended."""
    at: str
    step: ResearchStep
    detail: str

@dataclass(frozen=True, slots=True, kw_only=True)
class ResearchRunView:
    """A research run as `radar research log` and the admin show it: its id is its correlation id, which every log line and proposal of the run carries; the pages it read, the proposals it filed (among them the files it staged and the datasheets it read) and why others were rejected, what its model calls cost, and each step."""
    id: str
    scope: str
    actor: str
    started_at: str
    ended_at: str | None = None
    status: ResearchStatus
    token: str
    cad: float
    pages: tuple[str, ...]
    filed: tuple[str, ...]
    media: tuple[str, ...]
    datasheets: tuple[str, ...]
    rejected: tuple[str, ...]
    lines: tuple[ResearchLine, ...]

@dataclass(frozen=True, slots=True, kw_only=True)
class ResearchRunRow:
    """A research run as its list shows it: how many pages it read, proposals it filed (its files and datasheets among them) and had rejected, and its cost; its page shows what they were."""
    id: str
    scope: str
    actor: str
    started_at: str
    ended_at: str | None = None
    status: ResearchStatus
    cad: float
    pages: int
    filed: int
    rejected: int

@dataclass(frozen=True, slots=True, kw_only=True)
class ResearchRunList:
    """A page of the research runs, newest first, and how many there are."""
    runs: tuple[ResearchRunRow, ...]
    next: str | None = None
    total: int

    @property
    def cursor(self) -> str | None:
        return self.next

@dataclass(frozen=True, slots=True, kw_only=True)
class CategoryCells:
    """A category's profile cells: its products times the specs its profile shows (core and detail), and how many a claim no version range scopes fills."""
    cells: int
    before: int
    now: int

@dataclass(frozen=True, slots=True, kw_only=True)
class ResearchMeasures:
    """The research runs started since an instant, summed, as `radar research measure` prints them: the pages they read, what they skipped and had refused by why (a log line's text after its page, file or reason), the proposals they filed, the values (Claims) those put and how many of them a listing of their product's category filters on, those values by their proposal's status now and how many their product's page shows, each category's profile cells filled at the window's start and now, and what their model calls cost."""
    since: str
    runs: int
    pages: int
    skipped: Mapping[str, int]
    filed: int
    refused: Mapping[str, int]
    values: int
    filter_values: int
    statuses: Mapping[str, int]
    published: int
    cells: Mapping[str, CategoryCells]
    cad: float

@dataclass(frozen=True, slots=True, kw_only=True)
class ProductSheet:
    """A product as `radar product get` and the MCP server's get_product give it: its page's view, and the label and unit of each spec its rows name."""
    product: ProductView
    spec_definitions: Mapping[str, SpecLabel]

@dataclass(frozen=True, slots=True, kw_only=True)
class DocumentView:
    """A media Document as `radar source search` finds it: the digest and the address that dedupe its file, and the records it is about."""
    id: str
    kind: TermRef
    title: LocalizedText | None = None
    mime: str
    bytes: int
    sha256: str
    rights: TermRef
    source_url: str | None = None
    fetched_at: str
    subjects: tuple[str, ...]

@dataclass(frozen=True, slots=True, kw_only=True)
class FoundSources:
    """The catalog's Sources and media Documents a `radar source search` finds, each list newest first."""
    sources: tuple[SourceView, ...]
    documents: tuple[DocumentView, ...]

